$root = Split-Path $PSScriptRoot -Parent
$url='http://127.0.0.1:8765/api/state'; try { $state=Invoke-RestMethod $url; $account=Invoke-RestMethod 'http://127.0.0.1:8765/api/account'; $port=Get-NetTCPConnection -State Listen -LocalPort 8765; $pidFile=Join-Path (Split-Path $PSScriptRoot -Parent) 'state\binance-sniper.pid'; $process=Get-CimInstance Win32_Process -Filter "ProcessId = $($port.OwningProcess)"; [pscustomobject]@{ PID=$port.OwningProcess; Ownership=($process.CommandLine -match 'binance-sniper.*uvicorn binance_sniper\.app:app'); Transport=$state.transport_state; LastWsPayload=$state.last_ws_payload; LiveFeeds=@($state.feed_quality.PSObject.Properties.Value|Where-Object status -in 'LIVE_WS','LIVE_REST_FALLBACK').Count; Account=$account.auth; SnapshotAgeMs=$account.snapshot_age_ms; RegularOrders=$account.regular_orders; ConditionalOrders=$account.conditional_orders; ExecutionAlgoOrders=$account.execution_algo_orders; TotalOrders=$account.total_orders; SnapshotAt=$account.snapshot_at } | ConvertTo-Json -Depth 4 } catch { Write-Output 'Binance Sniper is not reachable on port 8765.'; exit 1 }
